#!/usr/bin/env bash
# Question 1: Pod ${Q1_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
rm -rf /opt/course/certs/${Q1_NAME}
mkdir -p /opt/course/certs/${Q1_NAME}
chown -R ubuntu:ubuntu /opt/course
openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/CN=${Q1_NAME}.${Q1_NS}.svc" -keyout "/opt/course/certs/${Q1_NAME}/tls.key" -out "/opt/course/certs/${Q1_NAME}/tls.crt" 2>/dev/null
chown -R ubuntu:ubuntu /opt/course
